import{_ as e}from"./chunks/architecture.Cs8uKTTN.js";import{_ as s,o as i,c as n,a2 as o}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Conceptos","description":"","frontmatter":{},"headers":[],"relativePath":"es/concepts/overview.md","filePath":"es/concepts/overview.md","lastUpdated":1784903584000}'),c={name:"es/concepts/overview.md"};function t(p,a,r,l,d,u){return i(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="conceptos" tabindex="-1">Conceptos <a class="header-anchor" href="#conceptos" aria-label="Permalink to &quot;Conceptos&quot;">​</a></h1><h2 id="arquitectura" tabindex="-1">Arquitectura <a class="header-anchor" href="#arquitectura" aria-label="Permalink to &quot;Arquitectura&quot;">​</a></h2><p>swag2mcp actúa como un puente entre las especificaciones de API y los agentes LLM:</p><img src="'+e+`" width="800" alt="Arquitectura de swag2mcp"><h2 id="conceptos-clave" tabindex="-1">Conceptos Clave <a class="header-anchor" href="#conceptos-clave" aria-label="Permalink to &quot;Conceptos Clave&quot;">​</a></h2><p><strong>Especificación</strong> — un contenedor lógico que representa un dominio o servicio de API (por ejemplo, YouTube, Binance, Open-Meteo). Cada especificación tiene un <code>domain</code> único, una <code>base_url</code>, <code>auth</code> opcional y contiene una o más colecciones. También puede establecer <code>llm_instruction</code> — una sugerencia corta inyectada en el prompt del sistema de swag2mcp que le dice al LLM para qué sirve esta especificación y cuándo usarla. Más información: <a href="./specs">Especificaciones</a>.</p><p><strong>Colección</strong> — un único archivo OpenAPI/Swagger/Postman que describe una API específica. Apunta a una <code>location</code> (URL o ruta de archivo local). Una especificación puede tener múltiples colecciones — por ejemplo, la especificación &quot;meteo&quot; podría tener colecciones &quot;Pronóstico&quot;, &quot;Calidad del Aire&quot; y &quot;Marino&quot;, cada una apuntando a un archivo de especificación diferente. Más información: <a href="./collections">Colecciones</a>.</p><p><strong>Etiqueta</strong> — una categoría de endpoints dentro de una colección. Ayuda al LLM a encontrar las operaciones correctas con más precisión. Más información: <a href="./tags">Etiquetas</a>.</p><p><strong>Endpoint</strong> — un método HTTP + ruta específico (por ejemplo, <code>GET /api/users</code>). El LLM puede encontrar un endpoint por descripción, inspeccionar sus parámetros y esquemas, y luego invocarlo. Más información: <a href="./endpoints">Endpoints</a>.</p><p><strong>Espacio de trabajo</strong> — el directorio donde swag2mcp almacena la configuración, la caché de especificaciones, las respuestas guardadas y los scripts de autenticación. Más información: <a href="./workspace">Espacio de Trabajo</a>.</p><h2 id="como-funciona" tabindex="-1">Cómo funciona <a class="header-anchor" href="#como-funciona" aria-label="Permalink to &quot;Cómo funciona&quot;">​</a></h2><ol><li><p><strong>Agregue una especificación o colección</strong> — defínala en la configuración YAML (<code>~/.swag2mcp/swag2mcp.yaml</code>). Por ejemplo:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">specs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Dad Joke API</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://icanhazdadjoke.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    collections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://raw.githubusercontent.com/mmadfox/swag2mcp/main/specs/dadjoke.yaml</span></span></code></pre></div></li><li><p><strong>swag2mcp analiza cada colección</strong> — crea Etiquetas y Endpoints, los indexa para búsqueda.</p></li><li><p><strong>El LLM encuentra el endpoint correcto</strong> — a través de herramientas MCP (<code>search</code>, <code>endpoint_by_tag</code>, <code>inspect</code>), el LLM busca un endpoint que coincida por descripción, revisa sus parámetros y esquema de solicitud.</p></li><li><p><strong>El LLM invoca el endpoint</strong> — a través de la herramienta MCP <code>invoke</code>, el LLM envía la solicitud. swag2mcp valida cada parámetro de entrada contra el esquema OpenAPI del endpoint (parámetros de ruta, parámetros de consulta, encabezados, cuerpo de solicitud) antes de realizar la llamada. Si algo no coincide con el esquema, el LLM recibe un error claro explicando qué está mal. Una vez validado, swag2mcp ejecuta la llamada HTTP real y devuelve el resultado.</p></li><li><p><strong>El resultado vuelve al LLM</strong> — la respuesta de la API se pasa de vuelta al agente. Las respuestas grandes se guardan en el espacio de trabajo y pueden explorarse con tres herramientas MCP dedicadas: <code>response_outline</code> (ver la estructura), <code>response_compress</code> (reducir a una muestra representativa) y <code>response_slice</code> (extraer fragmentos específicos).</p></li></ol><p>swag2mcp es un puente entre los LLM y el mundo de las APIs. Usted agrega especificaciones de API, y el LLM — a través del protocolo MCP — encuentra los endpoints correctos, inspecciona su documentación y los llama. Todo lo que necesita hacer es agregar una especificación e iniciar el servidor MCP.</p><blockquote><p><strong>La configuración se puede editar en cualquier momento.</strong> El archivo de configuración YAML (<code>~/.swag2mcp/swag2mcp.yaml</code>) se puede editar a mano — agregue especificaciones, cambie la autenticación, ajuste la configuración. Después de cada edición, reinicie el servidor MCP (<code>swag2mcp mcp</code>) para que los cambios surtan efecto.</p></blockquote><h2 id="jerarquia" tabindex="-1">Jerarquía <a class="header-anchor" href="#jerarquia" aria-label="Permalink to &quot;Jerarquía&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Especificación (dominio, por ejemplo &quot;meteo&quot;)</span></span>
<span class="line"><span>  └── Colección 1 (archivo de especificación, por ejemplo forecast.yml)</span></span>
<span class="line"><span>        └── Etiqueta 1 (categoría)</span></span>
<span class="line"><span>              └── Endpoint (GET /api/forecast)</span></span>
<span class="line"><span>              └── Endpoint (POST /api/forecast)</span></span>
<span class="line"><span>        └── Etiqueta 2</span></span>
<span class="line"><span>              └── Endpoint (GET /api/forecast/{id})</span></span>
<span class="line"><span>  └── Colección 2 (archivo de especificación, por ejemplo air-quality.yml)</span></span>
<span class="line"><span>        └── Etiqueta 3</span></span>
<span class="line"><span>              └── Endpoint (GET /api/air-quality)</span></span></code></pre></div>`,16)])])}const k=s(c,[["render",t]]);export{g as __pageData,k as default};
